(()=>{"use strict";const menu=document.querySelector(".menu-toggle"),nav=document.querySelector("#primary-nav"),year=document.querySelector("#year");if(year)year.textContent=String(new Date().getFullYear());if(menu&&nav){const close=()=>{menu.setAttribute("aria-expanded","false");nav.classList.remove("is-open")};menu.addEventListener("click",()=>{const open=menu.getAttribute("aria-expanded")!=="true";menu.setAttribute("aria-expanded",String(open));nav.classList.toggle("is-open",open)});nav.addEventListener("click",e=>{if(e.target instanceof HTMLAnchorElement)close()});document.addEventListener("keydown",e=>{if(e.key==="Escape"){close();menu.focus()}});window.addEventListener("resize",()=>{if(window.innerWidth>760)close()})}})();